use std::cell::RefCell;
use std::ops::{Deref, DerefMut};

use runtime::net::{IoBuf, IoBufMut};
use zeroize::Zeroize;

pub(crate) const BUFFER_SIZE: usize = 17 * 1024;

// `POOL_MAX_LEN` is generated by build.rs from the `POPPLE_POOL_MAX_LEN`
// env var (default 32). Set it in your application's `.cargo/config.toml`
// `[env]` table to tune the per-thread handshake-buffer pool ceiling.
include!(concat!(env!("OUT_DIR"), "/pool_config.rs"));

thread_local! {
    static POOL: RefCell<Vec<Box<[u8]>>> = const { RefCell::new(Vec::new()) };
}

pub(crate) struct PooledBuf {
    inner: Option<Box<[u8]>>,
}

impl PooledBuf {
    pub fn new() -> Self {
        let buf = POOL
            .with(|p| p.borrow_mut().pop())
            .unwrap_or_else(|| vec![0u8; BUFFER_SIZE].into_boxed_slice());
        PooledBuf { inner: Some(buf) }
    }
}

impl Deref for PooledBuf {
    type Target = [u8];
    fn deref(&self) -> &[u8] {
        self.inner.as_deref().unwrap()
    }
}

impl DerefMut for PooledBuf {
    fn deref_mut(&mut self) -> &mut [u8] {
        self.inner.as_deref_mut().unwrap()
    }
}

impl Drop for PooledBuf {
    fn drop(&mut self) {
        if let Some(mut buf) = self.inner.take() {
            buf.zeroize();
            POOL.with(|p| {
                let mut pool = p.borrow_mut();
                if pool.len() < POOL_MAX_LEN {
                    pool.push(buf);
                }
            });
        }
    }
}

// SAFETY:
// - The `Box<[u8]>` inside `inner` has a stable heap pointer that doesn't move
//   when `PooledBuf` (or the wrapping `Option`) is moved.
// - `bytes_init` returns the full box length, which is fixed at construction.
// - No lifetimes; satisfies `'static`. `Option<Box<[u8]>>` is `Unpin`.
// Callers that want to expose fewer than `BUFFER_SIZE` bytes to the kernel
// should wrap the buffer in `.slice(0..n)` (for sends) or `.tail(offset)`
// (for recvs, since `IoBufMut` has no slice form upstream).
unsafe impl IoBuf for PooledBuf {
    fn stable_ptr(&self) -> *const u8 {
        self.inner.as_ref().unwrap().as_ptr()
    }
    fn bytes_init(&self) -> usize {
        self.inner.as_ref().unwrap().len()
    }
}

impl PooledBuf {
    /// `IoBufMut` view of this buffer over `[offset, end)`: the kernel may
    /// only write into that window, so a recv appends after bytes already
    /// held (a partial record in the handshake deframer buffer) instead of
    /// landing in a scratch buffer that then has to be copied. `end` caps
    /// the write, e.g. to consume exactly up to a TLS record boundary.
    pub fn window(self, offset: usize, end: usize) -> PooledTail {
        assert!(
            offset <= end && end <= self.len(),
            "window [{offset}, {end}) out of pool buffer bounds"
        );
        PooledTail { buf: self, offset, end }
    }

    /// `window(offset, len)`: everything from `offset` to the end.
    pub fn tail(self, offset: usize) -> PooledTail {
        let end = self.len();
        self.window(offset, end)
    }
}

pub(crate) struct PooledTail {
    buf: PooledBuf,
    offset: usize,
    end: usize,
}

impl PooledTail {
    pub fn into_inner(self) -> PooledBuf {
        self.buf
    }
}

// SAFETY:
// - Inherits stable-pointer guarantee from `PooledBuf` (Box heap data); the
//   box does not move when the wrapper does.
// - `offset <= end <= len` is asserted at construction, so `ptr.add(offset)`
//   stays inside the allocation and `bytes_total = end - offset` keeps every
//   kernel write inside it too.
// - `set_init` is a no-op: the box length is fixed, and the caller uses the
//   recv's returned byte count to know how many bytes were written.
unsafe impl IoBufMut for PooledTail {
    fn stable_mut_ptr(&mut self) -> *mut u8 {
        unsafe { self.buf.as_mut_ptr().add(self.offset) }
    }
    fn bytes_total(&self) -> usize {
        self.end - self.offset
    }
    unsafe fn set_init(&mut self, _n: usize) {}
}
